import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
export const groupMigrationSources=fs.readdirSync(path.join(root,'supabase/migrations'))
  .filter(name=>/^2026101[56].*group_.*\.sql$/.test(name)).sort().slice(3);
const quote=value=>"'"+String(value).replace(/'/g,"''")+"'";
const marker='db03af60-8804-49f3-ba45-b47b67712077';

export function buildGroupStagingMigrationBundle(){
  if(groupMigrationSources.length!==9)throw Error('Expected exactly nine reviewed, pending GROUP migrations');
  const sources=groupMigrationSources.map((name,index)=>{
    const original=fs.readFileSync(path.join(root,'supabase/migrations',name),'utf8');
    const body=original.replace(/^begin;\s*$/gmi,'').replace(/^commit;\s*$/gmi,'').trim();
    const tag=`$verto_group_source_${index}$`;
    if(original.includes(tag)||original.includes('$verto_group_bundle$'))throw Error('SQL delimiter collision');
    return{name,version:name.slice(0,14),migrationName:name.slice(15,-4),body,tag,
      sha256:createHash('sha256').update(original).digest('hex')};
  });
  const names=sources.map(s=>quote(s.migrationName)).join(',');
  const manifest=sources.map(s=>`-- ${s.name} SHA256 ${s.sha256}`).join('\n');
  const operations=sources.map(s=>`  -- Original SQL, with only its outer BEGIN/COMMIT removed.
  v_sql:=${s.tag}\n${s.body}\n${s.tag};
  execute v_sql;
  insert into supabase_migrations.schema_migrations(version,name,statements)
  values(${quote(s.version)},${quote(s.migrationName)},array[v_sql]);`).join('\n\n');
  return `-- Verto GROUP sessions: remaining nine migrations. STAGING ONLY.
-- Target Supabase project: irspungjhapqdbgqroyc (Verto-Staging).
-- Generated by: node scripts/build-group-staging-migration-bundle.mjs
-- Does not reapply the first three migrations. No credentials or patient data.
-- The transaction rolls back every change on error; a complete replay is a no-op.
-- Run the whole file, not a selection. Review the displayed project before Run.
${manifest}
begin;
set local lock_timeout='10s';
set local statement_timeout='120s';
do $verto_group_bundle$
declare v_applied integer; v_sql text;
begin
  -- Two independent pre-existing markers bind this operation to our Staging DB.
  if not exists(select 1 from public.clinics where id='${marker}'::uuid
      and is_demo=true and billing_model='demo'
      and name='HOMOLOGAÇÃO FICTÍCIA SESSÕES EM GRUPO')
    or (select count(*) from supabase_migrations.schema_migrations
      where (version,name) in (
        ('20261016150342','group_session_specialty_rates'),
        ('20261016150343','group_session_private_rate_authority'),
        ('20261016150345','group_financial_rate_atomic_update')))<>3 then
    raise exception 'VERTO_STAGING_TARGET_REQUIRED: wrong database or missing reviewed prerequisites';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('verto-group-staging-migrations',0));
  select count(distinct name) into v_applied from supabase_migrations.schema_migrations where name in (${names});
  if v_applied=9 then
    if to_regprocedure('public.reserve_group_sessions_v1(uuid,uuid,uuid[],uuid[],text,uuid,jsonb,integer,text)') is null
      or to_regprocedure('public.list_group_sessions_v1(uuid,date,date)') is null then
      raise exception 'VERTO_GROUP_SCHEMA_HISTORY_MISMATCH';
    end if;
    raise notice 'All nine GROUP migrations already applied; no changes made';
    return;
  end if;
  if v_applied<>0 or to_regclass('public.group_session_bookings') is not null
    or exists(select 1 from supabase_migrations.schema_migrations where version in (${sources.map(s=>quote(s.version)).join(',')})) then
    raise exception 'VERTO_GROUP_PARTIAL_MIGRATION: inspect history and rebuild the pending set before proceeding';
  end if;
  if exists(select 1 from public.appointments where source_payload->>'sessionModality'='GROUP'
      or nullif(source_payload->>'sessionGroupId','') is not null) then
    raise exception 'VERTO_GROUP_UNREVIEWED_EXISTING_APPOINTMENTS';
  end if;

${operations}
end;
$verto_group_bundle$;
notify pgrst,'reload schema';
commit;

select 'STAGING_GROUP_MIGRATIONS_VERIFIED' as result,count(distinct name)::int as applied_remaining_migrations
from supabase_migrations.schema_migrations where name in (${names});
`;
}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  const output=path.join(root,'supabase/operations/group_sessions_staging_remaining.sql');
  fs.mkdirSync(path.dirname(output),{recursive:true});fs.writeFileSync(output,buildGroupStagingMigrationBundle());
  console.log('Generated '+path.relative(root,output)+' from nine unchanged migration sources');
}
